ALTER TABLE request_messages DROP CONSTRAINT IF EXISTS request_messages_sender_id_fkey; ALTER TABLE request_messages ADD CONSTRAINT request_messages_sender_id_fkey FOREIGN KEY (sender_id) REFERENCES public.user_profiles(id) ON DELETE CASCADE; DROP POLICY IF EXISTS Users can send messages if they see the request ON request_messages; CREATE POLICY Users can send messages if they see the request ON request_messages FOR INSERT TO authenticated WITH CHECK (auth.uid() = sender_id);
